<?php use Hls\Http\View as V; ?><section class="panel"><p>Nomor: <strong><?= V::escape($row['opname_ref']) ?></strong></p><p>Tanggal: <?= V::escape($row['opname_date']) ?> · Cabang: <?= V::escape($row['branch_code']) ?> · Gudang: <?= V::escape($row['warehouse_code']) ?></p><p>Status: <?= V::escape($row['status']) ?></p><?php foreach(['submit'=>'Kirim','verify'=>'Verifikasi','cancel'=>'Batalkan'] as $k=>$label): $perm=['submit'=>'inventory.opname.submit','verify'=>'inventory.opname.verify','cancel'=>'inventory.opname.cancel'][$k]; if($access->can($perm)): ?><form method="post" action="<?= $this->url('/inventory/stock-opname-transition') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="transition" value="<?= $k ?>"><button class="button"><?= $label ?></button></form><?php endif; endforeach ?></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Sistem</th><th>Fisik</th><th>Selisih</th><th>Satuan</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= V::escape($l['item_code'].' - '.$l['item_name']) ?></td><td><?= number_format((float)$l['system_qty'],3,',','.') ?></td><td><?= number_format((float)$l['physical_qty'],3,',','.') ?></td><td><?= number_format((float)$l['variance_qty'],3,',','.') ?></td><td><?= V::escape($l['unit_name']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
